// Generates a tiny deterministic gallery: solid-colour PNGs written byte-by-byte
// with zlib stored (uncompressed) deflate blocks, so the bytes depend only on the
// declared colour and size. No network, no image library.
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const crypto = require('crypto');

function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length, 0);
  const td = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(td) >>> 0, 0);
  return Buffer.concat([len, td, crc]);
}
let TBL = null;
function crc32(buf) {
  if (TBL === null) {
    TBL = [];
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      TBL[n] = c >>> 0;
    }
  }
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = TBL[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function png(width, height, rgb) {
  const raw = Buffer.alloc((width * 3 + 1) * height);
  let o = 0;
  for (let y = 0; y < height; y++) {
    raw[o++] = 0;
    for (let x = 0; x < width; x++) { raw[o++] = rgb[0]; raw[o++] = rgb[1]; raw[o++] = rgb[2]; }
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0); ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; ihdr[9] = 2; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', zlib.deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}
const out = process.argv[2];
fs.mkdirSync(out, { recursive: true });
const set = [
  { name: 'a-crimson.png', rgb: [200, 30, 40], w: 64, h: 48 },
  { name: 'b-forest.png', rgb: [30, 140, 60], w: 64, h: 48 },
  { name: 'c-indigo.png', rgb: [50, 60, 190], w: 64, h: 48 },
];
const files = [];
for (const s of set) {
  const bytes = png(s.w, s.h, s.rgb);
  fs.writeFileSync(path.join(out, s.name), bytes);
  files.push({
    name: s.name, width: s.w, height: s.h, rgb: s.rgb, bytes: bytes.length,
    sha256: crypto.createHash('sha256').update(bytes).digest('hex'),
  });
}
process.stdout.write(JSON.stringify({ dir: out, files }, null, 2) + '\n');
